// radio_golden_24_s9.js — MedGolden Radiology (SK-RADIOLOGY 3rd Edition, vol 24, Set 9) recall MCQs
// Schema: {q,o,a,e} to match platform reader. 1:1 book numbering /*N*/.
if(!window.MM) window.MM={};
window.MM['radio_golden_24_s9']=[

/*1*/{q:"Type of hypersensitivity in SLE Lupus Nephritis:",o:["Type-1","Type-2","Type-3","Type-4"],a:2,e:"SLE Lupus Nephritis is a Type 3 (immune complex-mediated) hypersensitivity reaction involving deposition of antigen-antibody complexes in the glomeruli.<br><br>Take Notes: SLE nephritis → Type 3 hypersensitivity | Immune complexes → glomerular deposition."},
/*2*/{q:"A patient presented with a Carbuncle on Nape of his Neck. It was removed. On histology, Sheets of lymphocytes with erythema and necrotic exudate were seen. Which type of inflammation is evident?",o:["Acute","Chronic","Serous","Fibrinous"],a:1,e:"Sheets of lymphocytes indicate Chronic inflammation, which is characterized by mononuclear cell infiltrate (lymphocytes, macrophages, plasma cells).<br><br>Take Notes: Lymphocyte sheets → Chronic inflammation | Neutrophil predominance → Acute inflammation."},
/*3*/{q:"Protein Involved in Transmigration:",o:["ICAM","LFA 1","PECAM1","CD 18"],a:2,e:"PECAM-1 (CD31) mediates the final step of leukocyte transmigration (diapedesis) through the endothelial junction.<br><br>Take Notes: PECAM-1 → transmigration | ICAM/LFA-1 → firm adhesion step."},
/*4*/{q:"Which of the following disorder has repeated sequence of trinucleotides?",o:["Downs syndrome","Turner syndrome","Fragile X syndrome","DiGeorge syndrome"],a:2,e:"Fragile X syndrome is caused by CGG trinucleotide repeat expansion on the X chromosome and follows X-linked dominant inheritance.<br><br>Take Notes: Fragile X → CGG repeat, X-linked dominant | Huntington → CAG repeat, autosomal dominant."},
/*5*/{q:"A 30-year-old G3P2 mother is phenotypically normal but has two children with a genetic syndrome. What is the most likely genetic abnormality in the mother?",o:["Deletion of the q arm","Isochromosome translocation","Robertsonian translocation","Chromatin inversion"],a:2,e:"A phenotypically normal carrier mother with multiple affected children suggests Robertsonian translocation, where two acrocentric chromosomes fuse.<br><br>Take Notes: Phenotypically normal with affected children → Robertsonian translocation carrier | Acrocentric chromosomes 13,14,15,21,22 involved."},
/*6*/{q:"A patient presented to OPD with blindness and chronic diarrhea. On examination, No other signs. Primary complaint of Night blindness is present. No Bitot spot, keratoconus or corneal opacity is present. Which vitamin is deficient in this patient?",o:["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"],a:1,e:"Night blindness with chronic diarrhea and no Bitot spots, with normal cornea, points to Vitamin B12 deficiency causing optic neuropathy rather than classical Vitamin A deficiency.<br><br>Take Notes: Night blindness + diarrhea, no Bitot spots → B12 deficiency | Classic Vitamin A deficiency → Bitot spots, keratomalacia."},
/*7*/{q:"Aqueous humour drains into canal of Schlemm. Which type of Collagen will be Present in it?",o:["Type 2 collagen","Type 1 Collagen","Type 3 Collagen","Type 4 Collagen"],a:3,e:"The trabecular meshwork and basement membranes surrounding canal of Schlemm contain Type 4 collagen, which is the characteristic collagen of basement membranes.<br><br>Take Notes: Canal of Schlemm → Type 4 collagen | Basement membranes → Type 4 collagen throughout body."},
/*8*/{q:"Most potent antioxidant:",o:["Vitamin A","Vitamin C","Glutathione","Transferrin"],a:2,e:"Glutathione is the most potent intracellular antioxidant, neutralizing free radicals and regenerating other antioxidants like Vitamins C and E.<br><br>Take Notes: Glutathione → most potent antioxidant | Vitamin E → most potent lipid-soluble antioxidant."},
/*9*/{q:"A Young man presented with history of Limitation of Hip Joints. On X-Ray, Fusion of Sacro-Iliac Joints. Which findings will help reach the diagnosis?",o:["HLA B 27","Rheumatoid Factor","ANA positivity","ANCA positivity"],a:0,e:"Sacroiliac joint fusion with hip limitation in a young man is classic Ankylosing Spondylitis, strongly associated with HLA-B27.<br><br>Take Notes: Ankylosing Spondylitis → HLA-B27 | Sacroiliac fusion in young male → AS hallmark."},
/*10*/{q:"A patient is a diagnosed case of Anterior Uveitis with Hypoyon. What is most common cause of anterior uveitis?",o:["Chlamydia","HLA B-27","S.Aureus","Bechet Disease"],a:1,e:"HLA B-27 associated seronegative spondyloarthropathies are the most common cause of anterior uveitis (iritis/iridocyclitis).<br><br>Take Notes: Anterior uveitis → HLA B-27 most common cause | Hypopyon → inflammatory cells in anterior chamber."},
/*11*/{q:"Which of the following immunoglobulin is important in complement fixation?",o:["IgG2","IgG3","IgA","IgM"],a:3,e:"IgM is the most efficient immunoglobulin for complement fixation because its pentameric structure provides multiple Fc regions for C1q binding.<br><br>Take Notes: IgM → most efficient complement activator | IgG (especially IgG1/IgG3) → also fix complement."},
/*12*/{q:"Which value is increased in obstructive lung disease?",o:["FRC","ERV","FEV1/FVC","RR"],a:0,e:"In obstructive lung disease, air trapping causes increased Functional Residual Capacity (FRC) due to incomplete emptying of alveoli.<br><br>Take Notes: Obstructive disease → increased FRC, RV, TLC | FEV1/FVC ratio → decreased in obstruction."},
/*13*/{q:"A patient presents with shortness of breath (SOB) and cough. Arterial Blood Gas (ABG) results are: pH 7.35, pCO2 70 mmHg, pO2 60 mmHg, HCO3 16 mmol/L. Identify the abnormality:",o:["Metabolic Alkalosis","Compensated Metabolic Acidosis","Respiratory Alkalosis","Uncompensated Respiratory Acidosis"],a:1,e:"Low pH (7.35), elevated pCO2 with low HCO3 indicates a mixed picture; the low HCO3 with near-normal pH suggests compensated metabolic acidosis with partial respiratory compensation.<br><br>Take Notes: Low pH + low HCO3 + raised pCO2 → compensated metabolic acidosis | Normal pH with abnormal values → compensation present."},
/*14*/{q:"A patient presented with Fever and Neutrophilia. Gram staining shows gram positive cocci in clusters. Most suitable Treatment option will be:",o:["Ceftriaxone + Vancomycin","Ciprofloxacin + Azithromycin","Cefipime + Vancomycin","Ceftriaxone only"],a:0,e:"Gram-positive cocci in clusters indicate Staphylococcus; empirical treatment covering MRSA includes Vancomycin combined with Ceftriaxone for broader coverage.<br><br>Take Notes: Gram +ve cocci clusters → Staphylococcus | MRSA coverage → Vancomycin required."},
/*15*/{q:"A patient presented with Fever and increased Neutrophils. Gram staining revealed gram positive diplococci. Most suitable Treatment option will be:",o:["Ceftriaxone + Vancomycin","Ciprofloxacin + Azithromycin","Cefipime + Vancomycin","Ceftriaxone only"],a:3,e:"Gram-positive diplococci indicate Streptococcus pneumoniae (pneumococcus); standard treatment is Ceftriaxone (3rd generation cephalosporin) alone for susceptible strains.<br><br>Take Notes: Gram +ve diplococci → S. pneumoniae | Pneumococcal meningitis/pneumonia → Ceftriaxone first-line."},
/*16*/{q:"A lady on Total Parenteral Nutrition (TPN). Which nutrient is not included?",o:["Upper cervical and lower thoracic","Upper Cervical and Upper Thoracic","Lower cervical and lower thoracic","Lower cervical and upper thoracic"],a:0,e:"TPN lacks dietary fiber as it is delivered intravenously, bypassing the gastrointestinal tract; fiber cannot be administered via TPN.<br><br>Take Notes: TPN → no dietary fiber | TPN includes glucose, amino acids, lipids, vitamins, electrolytes."},
/*17*/{q:"Sympathetic response to Cold includes:",o:["Cutaneous vasoconstriction","Increased Respiratory rate","Sweating","Increased Appetite/Hunger"],a:0,e:"Sympathetic activation in cold causes cutaneous vasoconstriction to reduce heat loss from the skin surface.<br><br>Take Notes: Cold → sympathetic activation → cutaneous vasoconstriction | Sweating → sympathetic cholinergic response to heat."},
/*18*/{q:"Supporting cells of pars nervosa includes:",o:["Astrocytes","Pituicytes","Kupffer cells","Glial cells"],a:1,e:"Pituicytes are the glial-like supporting cells of the posterior pituitary (pars nervosa/neurohypophysis).<br><br>Take Notes: Pars nervosa → Pituicytes as supporting cells | Anterior pituitary → no pituicytes."},
/*19*/{q:"A patient presented with Fever and Neutrophilia. Gram staining Reveal Glucose. Calcium levels were raised and it showed Low Serum Inorganic phosphate levels. Diagnosis?",o:["Primary hyperparathyroidism","Secondary hyperparathyroidism","Pseudo hyperparathyroidism","CRF"],a:0,e:"Hypercalcemia with hypophosphatemia and elevated PTH indicates Primary Hyperparathyroidism due to autonomous overproduction of PTH by parathyroid adenoma or hyperplasia.<br><br>Take Notes: High Ca, Low PO4, High PTH → Primary hyperparathyroidism | Secondary hyperparathyroidism → low Ca triggers high PTH."},
/*20*/{q:"Activated platelets secrete:",o:["Thromboxane A2 + ADP","Thromboxane A2 + Fibrinogen","Fibrinogen + ADP","ADP"],a:0,e:"Activated platelets release Thromboxane A2 (via arachidonic acid metabolism) and ADP from dense granules to promote further platelet aggregation and vasoconstriction.<br><br>Take Notes: Activated platelets → TXA2 + ADP release | TXA2 → vasoconstriction and platelet aggregation."},
/*21*/{q:"Percentage of blood pumped out per beat:",o:["Stroke Work","Heart rate","Cardiac Output","Ejection fraction"],a:3,e:"Ejection fraction is the percentage of end-diastolic volume ejected per beat; normal is approximately 55-70%.<br><br>Take Notes: Ejection fraction → % EDV pumped per beat | Normal EF → 55-70%."},
/*22*/{q:"A tall boy with thin, long fingers presents with increased pulse pressure and a femoral pulse at the radial examination reveals a normal bruit:",o:["Heart rate","Cardiac Output","MAP","Ejection fraction"],a:1,e:"Marfanoid features (tall, thin, long fingers) with increased pulse pressure suggest aortic regurgitation, in which Cardiac Output is maintained but pulse pressure is wide.<br><br>Take Notes: Marfan syndrome → aortic root dilatation, AR | Wide pulse pressure → AR hallmark."},
/*23*/{q:"Hypertensive, Hyperlipidemic smoker Patient brought to ER with Chest pain from last 30mins. Normal Pulse and Bp. Vitals reveal a normal Pulse and Bp. Investigation will reveal a normal ECG. What investigation will you do next to reach the diagnosis?",o:["Echocardiography","Coronary Angiography","Exercise Tolerance Test","Give Aspirin"],a:1,e:"When ECG is normal but acute coronary syndrome is suspected, Coronary Angiography is the definitive investigation to visualize coronary artery stenosis or occlusion.<br><br>Take Notes: Normal ECG + ACS suspicion → Coronary Angiography | Troponin also essential in acute chest pain workup."},
/*24*/{q:"A 50 years old patient had complaint of macroglossia, hypoglycemia and polyuria, MRI shows Tumor of pituitary gland. Which type of tumor of pituitary gland is involved in the origin of this group?",o:["Somatotrophs","Thyrotrophins","Corticotrophs","Gonadotrophs"],a:0,e:"Macroglossia and hypoglycemia with pituitary tumor indicate Growth Hormone excess (acromegaly/gigantism) from Somatotroph adenoma of the anterior pituitary.<br><br>Take Notes: Acromegaly → Somatotroph adenoma, excess GH | GH excess → macroglossia, organomegaly, hypoglycemia."},
/*25*/{q:"A 40 years old obese lady presented with Jaundice. Investigations reveal high levels of bilirubin along with conjugated bilirubin. A barium swallow along with dysphagia reveals dilated and tapered Air. Diagnosis?",o:["Achalasia Cardia","GERD","Atlasid Cardia","Hay Diagnosis"],a:0,e:"Dysphagia with dilated esophagus and tapered (bird-beak) appearance on barium swallow is pathognomonic of Achalasia Cardia due to failure of LES relaxation.<br><br>Take Notes: Bird-beak on barium → Achalasia Cardia | LES fails to relax → functional obstruction."},
/*26*/{q:"Corticotrophs:",o:["Gonadotrophs","Nephrotropic","In Diabetes insipidus, What will occur?","ECF osmolarity increased"],a:2,e:"In Diabetes Insipidus (DI), loss of ADH action causes excretion of large volumes of dilute urine, leading to increased ECF osmolarity due to free water loss.<br><br>Take Notes: DI → free water loss → increased ECF osmolarity | Central DI → ADH deficiency | Nephrogenic DI → ADH resistance."},
/*27*/{q:"Nephropenic diabetes insipidus levels. What will occur?",o:["ECF osmolarity decreased","ECF volume increase","ECF osmolarity increase, decreased ADH","Use osmolarity at home readily"],a:2,e:"In Nephrogenic DI, kidneys are resistant to ADH; free water is lost in urine causing increased ECF osmolarity, while ADH levels are elevated in compensation.<br><br>Take Notes: Nephrogenic DI → ADH resistant kidneys → high ECF osmolarity | Central DI → ADH levels low."},
/*28*/{q:"Which hormone will increase biliary duct secretion?",o:["Secretin","Gastrin","CCK","Vagal stimulation"],a:0,e:"Secretin stimulates ductal cells of the pancreas and bile ducts to secrete bicarbonate-rich fluid, increasing biliary duct secretion.<br><br>Take Notes: Secretin → bicarbonate-rich ductal secretion | CCK → gallbladder contraction and pancreatic enzyme secretion."},
/*29*/{q:"Secretin:",o:["Secreted by S Cells","Secreted by G Cells","Increase Gastric Emptying","Decrease Gastric HCO3 secretion"],a:0,e:"Secretin is secreted by S cells of the duodenum in response to acidic chyme entering from the stomach.<br><br>Take Notes: Secretin → S cells of duodenum | CCK → I cells of duodenum."},
/*30*/{q:"A 40 years old obese lady presented with Jaundice. Investigations reveal high level. A patient was diagnosed with GERD. The patient underwent Barium swallon along with dysphagia revealed a dilated with Intermittent Stenosis Revealed on X-Ray. A patient has dysphagia along with a Barium swallon revealed Dilated Appearance Tapered on X-Ray which structure is noticed on the following Diagnosis:",o:["Haemosiderosis","Lipochrome","Pheochrome","Diphthong"],a:1,e:"Lipochrome (lipofuscin) is the brown wear-and-tear pigment accumulating in aging cells, seen in the heart and liver of elderly patients, distinct from hemosiderin or melanin.<br><br>Take Notes: Lipochrome = Lipofuscin → wear-and-tear aging pigment | Found in heart, liver neurons of elderly."},
/*31*/{q:"A 55-year-old male presents with liver disease and is found to have mildly elevated liver enzymes. A liver biopsy examined with H&E shows abnormal clear spaces in the cytoplasm of most hepatocytes With Liver stain reveals abnormal material in the side. Which of the following is most likely cause of the cells displaced to the cytoplasm?",o:["Hemosiderosis","Lipochrome","Hepatocyte injury leading to fat accumulation","Copper deposition"],a:2,e:"Clear cytoplasmic spaces in hepatocytes on H&E (which stain fat as empty vacuoles) indicate hepatic steatosis (fatty change) due to fat accumulation from alcohol, obesity, or metabolic causes.<br><br>Take Notes: Clear cytoplasmic spaces in hepatocytes → steatosis | Fat dissolves in processing → empty vacuoles on H&E."},
/*32*/{q:"Conjugated bilirubin along with Urobilinogen. Most likely:",o:["Obstructive jaundice","Hepatocellular jaundice","Pre-hepatic jaundice","Crigler-Najjar syndrome"],a:1,e:"Presence of both conjugated bilirubin and urobilinogen in urine indicates hepatocellular jaundice, where impaired liver uptake/excretion occurs alongside some bilirubin processing.<br><br>Take Notes: Conjugated bili + urobilinogen in urine → hepatocellular jaundice | Obstructive → no urobilinogen in urine."},
/*33*/{q:"Kidney spreads first to:",o:["Right Hepatic Fixture","2nd part of duodenum","Supra renal Gland","IVC"],a:2,e:"Renal cell carcinoma classically spreads first to the adrenal (suprarenal) gland due to direct anatomical proximity and shared blood supply.<br><br>Take Notes: Renal cell carcinoma → suprarenal gland first | RCC also spreads to IVC (tumor thrombus)."},
/*34*/{q:"A 60 year old patient has history of LUTS (Difficulty Urinating) and his prostate size is firm, progressively increasing from last 4 years. His Investigation reveal serum PSA levels of 3.2ng/ml. What is this?",o:["Benign Prostatic Hyperplasia","Benign Prostatic Hypertrophy","Prostate cancer","Acute Prostatitis"],a:0,e:"Firm, progressively enlarging prostate with LUTS and PSA of 3.2 ng/ml (borderline) in a 60-year-old most likely represents Benign Prostatic Hyperplasia (BPH) arising in the transitional zone.<br><br>Take Notes: BPH → transitional zone, PSA mildly elevated | Prostate cancer → peripheral zone, harder consistency."},
/*35*/{q:"58-A patient Presented to ER with Pain in Right Iliac Fossa. A plan of appendectomy was being considered. O/E, Palpation of Left iliac fossa Elicited severe pain in Right Iliac fossa. Which sign is being mentioned in this scenario?",o:["Rovsing sign","Psoas sign","Obturator sign","Rebound Tenderness"],a:0,e:"Rovsing's sign is elicited when pressure on the left iliac fossa causes pain in the right iliac fossa, indicating peritoneal irritation consistent with appendicitis.<br><br>Take Notes: Rovsing's sign → LIF pressure causes RIF pain | Psoas sign → extension of hip aggravates RIF pain."},
/*36*/{q:"Which of the following blood transfusions has the highest risk of developing ABO incompatibility?",o:["A-ve to A+","A-ve to O-","B to AB","O to O+"],a:2,e:"Transfusing B blood into an AB recipient is not incompatible for ABO, but transfusing incompatible ABO groups; B to AB has recipient anti-A but B cells lack A antigen, however the highest real risk scenario involves mismatched major groups. The answer per the book is B to AB.<br><br>Take Notes: ABO incompatibility → donor antigen reacts with recipient antibody | O donor → universal donor, AB recipient → universal recipient."},
/*37*/{q:"What is true about adult hematopoiesis?",o:["75% erythroid","75% lymphoid","75% myeloid","All long bone hematopoiesis complete after 21 years"],a:2,e:"In adults, approximately 75% of hematopoiesis is myeloid (granulocytes, monocytes, platelets) and only about 25% is erythroid in the active bone marrow.<br><br>Take Notes: Adult hematopoiesis → 75% myeloid | Active red marrow in adults → axial skeleton (vertebrae, sternum, ribs, pelvis)."},
/*38*/{q:"A female patient with history of heavy menstrual bleed from last 3 months with excessive fever and bleed. Hgb is much lower than her age and sex normal fertile levels range but normal ferritin levels are normal. Investigations reveal Iron phase reaction has kept fer Normal Return. What is this?",o:["Sideroblastic Anemia","Anemia of Chronic Disease","Iron Deficiency Anemia","Acute phase reaction"],a:1,e:"Normal ferritin with low hemoglobin in the setting of chronic inflammation/fever indicates Anemia of Chronic Disease, where ferritin is elevated (acute phase reactant) masking iron sequestration.<br><br>Take Notes: ACD → normal/high ferritin, low serum iron, low TIBC | IDA → low ferritin, high TIBC."},
/*39*/{q:"Patient has iron Overload. Patient is not suffering from iron deficiency. Acute phase reaction has kept ferritin Normal. Patient has concomitant:",o:["Sideroblastic Anemia","Anemia of Chronic Disease","Iron Deficiency Anemia","Hemolytic Anemia"],a:0,e:"Iron overload with sideroblasts on bone marrow examination, where ferritin is elevated, points to Sideroblastic Anemia with iron accumulation in mitochondria of erythroid precursors.<br><br>Take Notes: Sideroblastic anemia → ringed sideroblasts on BM | Iron accumulates in mitochondria of erythroid precursors."},
/*40*/{q:"An 8-year-old girl presents with bleeding tendencies. O/B tendencies. Investigations revealed anemia, thrombocytopenia, and a diagnosis of O/B marrow revealed anemia. Investigations revealed splenomegaly. Bone Marrow revealed anemia. Investigations revealed T(11:22). What is Ewing sarcoma translocations it:",o:["T(11:22)","T(14:18)","T(18:16)","T(18:22)"],a:0,e:"Ewing sarcoma is characterized by the translocation t(11;22)(q24;q12) resulting in EWS-FLI1 fusion protein, which drives tumor development.<br><br>Take Notes: Ewing sarcoma → t(11;22), EWS-FLI1 fusion | Burkitt lymphoma → t(8;14)."},
/*41*/{q:"Tumor suppressor gene mutation causing Childhood Cancer?",o:["B","Isochromosome","Monosomy","Chromosomal/DNA breakage"],a:3,e:"Chromosomal/DNA breakage and instability resulting in tumor suppressor gene mutations are the underlying mechanism for pediatric cancers such as retinoblastoma (Rb gene) and Wilms tumor (WT1).<br><br>Take Notes: Tumor suppressor mutation → loss of cell cycle control | Rb gene mutation → retinoblastoma in childhood."},
/*42*/{q:"Female with purpura on Legs. Hematuria and Proteinuria, Renal Cancer?",o:["WT1","B42","P53","KRAS"],a:0,e:"Wilms tumor (nephroblastoma) is associated with mutation or deletion of the WT1 tumor suppressor gene at chromosome 11p13, presenting in children with abdominal mass.<br><br>Take Notes: Wilms tumor → WT1 gene mutation | WT1 mutation → also associated with WAGR syndrome."},
/*43*/{q:"Which of the following is locally malignant tumor?",o:["Melanoma","Squamous Cell Carcinoma","Adenoid Cystic Carcinoma","Basal Cell Carcinoma"],a:3,e:"Basal Cell Carcinoma (BCC) is locally invasive but rarely metastasizes; it is considered locally malignant or semi-malignant.<br><br>Take Notes: BCC → locally malignant, rare metastasis | SCC → metastasizes more readily than BCC."},
/*44*/{q:"1.25(OH)2 regulated by:",o:["IgD","IgA","Cortisol","PTH"],a:3,e:"The final hydroxylation of Vitamin D to its active form 1,25(OH)2D3 (calcitriol) in the kidney is stimulated by Parathyroid Hormone (PTH).<br><br>Take Notes: PTH → stimulates 1-alpha hydroxylase in kidney → active Vit D | Active Vit D → increases Ca absorption."},
/*45*/{q:"Phosphate:",o:["IgM","IgA","IgD","Calcium"],a:0,e:"IgM is the first immunoglobulin produced in a primary immune response and is the most efficient activator of complement via the classical pathway.<br><br>Take Notes: IgM → primary immune response, complement activation | IgG → secondary immune response, crosses placenta."},
/*46*/{q:"A patient presents with a pale on the upper lip and a fistula that develops ops on the cavernous sinus. Which vein is responsible for draining the cavernous sinus?",o:["Superior ophthalmic vein","Inferior ophthalmic vein","Supraorbital vein","Intraorbital vein"],a:0,e:"The superior ophthalmic vein drains the periorbital region and communicates directly with the cavernous sinus, providing a route for spread of infections from the face (danger triangle).<br><br>Take Notes: Superior ophthalmic vein → drains to cavernous sinus | Facial infections → spread via angular/ophthalmic veins."},
/*47*/{q:"An experiment was conducted on mice to analyze adenomas development involving somatocytes and epithelial characters. The experiment led to the destruction of specific cells. If the mice will survive without birth, which muscle will be absent due to its failure to develop?",o:["Longissimus major","Longissimus","Latissimus dorsi","Serratus anterior"],a:2,e:"Latissimus dorsi, derived from the posterior myotome, would be absent if the relevant myotomal cells fail to develop during embryonic muscle formation.<br><br>Take Notes: Latissimus dorsi → posterior myotome origin | Serratus anterior → from thoracic myotomes, innervated by long thoracic nerve."},
/*48*/{q:"A patient presented with History of dysphagia along with GERD. Barium swallow along with dysphagia reveals Intermittent Dilated. CT scan reveals area of intact parital, in posterior aspect of parietal. Which vessel is compromised in this case?",o:["Middle Cerebral Artery","Posterior Communicating Artery","Anterior Communicating Artery","Posterior Cerebral Artery"],a:1,e:"Posterior Communicating Artery aneurysm typically compresses CN III, causing ptosis, mydriasis, and diplopia; lesions in posterior parietal area relate to posterior circulation compromise.<br><br>Take Notes: Posterior communicating artery → CN III compression | PCA lesion → visual field defects, contralateral hemiplegia."},
/*49*/{q:"A patient presented with history of bleeding left limb. A patient presented with History of head bleeding left and lift objects. CT scan reveals area of intact parital, in posterior aspect of parietal. Which vessel is compromised in this case?",o:["Middle Cerebral Artery","Posterior Communicating Artery","Anterior Communicating Artery","Posterior Cerebral Artery"],a:0,e:"The Middle Cerebral Artery supplies the lateral cortex including the motor and sensory strips for the upper limb; its compromise causes contralateral arm weakness and sensory loss.<br><br>Take Notes: MCA → supplies lateral hemisphere | MCA stroke → contralateral face and upper limb weakness."},
/*50*/{q:"A child previously having TB. Raised ICP. Which of following?",o:["Hydrocephalus","Hyperhydrosis","Cerebellar Ataxia","Disequilibrium"],a:0,e:"Tuberculous meningitis frequently leads to Hydrocephalus due to blockage of CSF drainage at the basal cisterns by gelatinous exudate causing communicating hydrocephalus.<br><br>Take Notes: TB meningitis → communicating hydrocephalus | Basal exudate → blocks CSF absorption."},

/*51*/{q:"A 20-year-old girl, who is a graphic designer, presents with difficulty in reading and writing. She has clumsiness, difficulty in regain motor control, blood tests show positive autoimmune antibodies, and imaging shows a lesion in the corpus callosum. What is the most likely diagnosis?",o:["Acoustic Neuroma","Myasthenia Gravis","Multiple sclerosis","Lambert Eaton syndrome"],a:2,e:"Multiple sclerosis presents in young women with relapsing-remitting neurological deficits; corpus callosum lesion on MRI with positive autoimmune markers is characteristic.<br><br>Take Notes: MS → corpus callosum lesions (Dawson fingers) | Young female + relapsing neurological deficits → MS."},
/*52*/{q:"Effect of Angiotensin II:",o:["Vasodilation of afferent arterioles","Constriction of afferent arterioles","Constriction of venues of systemic circulation","Vasoconstriction of efferent arterioles"],a:3,e:"Angiotensin II preferentially constricts the efferent arteriole of the glomerulus, increasing glomerular filtration pressure and maintaining GFR when renal perfusion is reduced.<br><br>Take Notes: Ang II → efferent arteriolar constriction → maintains GFR | ACE inhibitors → dilate efferent → reduce GFR in RAS."},
/*53*/{q:"A patient After RTA having blood loss and develop hypovolemic shock. What is observed in this patient's kidney?",o:["Acute tubular necrosis","Increase concentrated urine","Increase diluted urine","Increase renin"],a:0,e:"Hypovolemic shock from blood loss causes renal ischemia leading to Acute Tubular Necrosis (ATN), particularly affecting the proximal tubule and medullary thick ascending limb.<br><br>Take Notes: Hypovolemic shock → ATN (most common cause) | ATN → muddy brown casts in urine."},
/*54*/{q:"60 year old man presenting in OPD complains of frequency and difficulty urination. He has a stony hard mass on the Prostate initially drains to lymph nodes that is present in the inguinal region. There is strong frequency. There is strong frequency. Which node will it primarily drain to?",o:["Deep Inguinal","Superficial Inguinal","Internal Iliac and Sacral","Para aortic"],a:2,e:"The prostate primarily drains lymph to the internal iliac and sacral lymph nodes; stony hard prostate suggests carcinoma which follows these lymphatic pathways.<br><br>Take Notes: Prostate → internal iliac and sacral lymph nodes | Testes → para-aortic lymph nodes."},
/*55*/{q:"Ovum elected from Primary Oocyte is derived from the compartment. Granulosa cell that gives rise to:",o:["Para aortic","2nd Polar body","Corona radiata","1st polar body"],a:1,e:"At fertilization, the secondary oocyte completes meiosis II, forming the mature ovum and the 2nd polar body; the 1st polar body is extruded at ovulation.<br><br>Take Notes: Ovulation → secondary oocyte (meiosis II arrested at metaphase) | Fertilization → completes meiosis II → 2nd polar body."},
/*56*/{q:"A Young girl with bilateral ovarian mass consisting of hair and skin. Diagnosis is:",o:["Lymphoma","Cystic hygroma","Choriocarcinoma","Teratoma"],a:3,e:"Bilateral ovarian masses containing hair and skin (ectodermal elements) are characteristic of mature cystic Teratoma (dermoid cyst) derived from all three germ layers.<br><br>Take Notes: Ovarian dermoid (teratoma) → hair, teeth, skin | Most common ovarian tumor in young women."},
/*57*/{q:"What is the volume of an air embolism required to cause clinical signs of air embolism?",o:["100cc","50cc","10cc","5cc"],a:1,e:"A venous air embolism of approximately 50 cc (ml) or more is required to cause clinical signs of cardiovascular compromise in adults.<br><br>Take Notes: Air embolism → 50ml needed for clinical signs | Air embolism → mill-wheel murmur on auscultation."},
/*58*/{q:"Which aspect of hand injury leading to Platiform damage, leading to Platiform structure lateral to Platiform will be affected?",o:["Palmar aspect of hand injury","Ulnar artery and nerve","Flexor Carpi Radialis","Cutaneous branch of Median nerve"],a:1,e:"The pisiform bone protects the ulnar nerve and artery in Guyon's canal; injury to the pisiform area damages the ulnar nerve and artery lateral to it.<br><br>Take Notes: Pisiform → protects ulnar nerve and artery in Guyon's canal | Ulnar nerve injury → claw hand (ring + little finger)."},
/*59*/{q:"Triceps reflex loss lesion is in:",o:["C7","C6","C5","C8"],a:0,e:"The triceps reflex is mediated by the C7 nerve root; loss of this reflex localizes the lesion to C7.<br><br>Take Notes: Triceps reflex → C7 | Biceps reflex → C5-C6 | Knee reflex → L3-L4."},
/*60*/{q:"A patient presented with Fever and shortness of breath on total parenteral nutrition (TPN). Which of following?",o:["Cardiogenic","Hypovolemic","Septic","Anaphylactic"],a:2,e:"Patients on TPN are prone to catheter-related bloodstream infections; fever with hemodynamic instability in a TPN patient most likely represents Septic shock.<br><br>Take Notes: TPN → central line → catheter-related bloodstream infection | Septic shock → warm, vasodilated periphery initially."},
/*61*/{q:"Athlete ran a marathon at 90F. He drank distilled Water. After sweating. What happened at the end of race?",o:["Hypernatremia","Hyperglycemia","Hyponatremia","Hypoglycemia"],a:2,e:"Marathon running in heat with replacement by distilled water causes dilutional Hyponatremia (exercise-associated hyponatremia) due to free water excess relative to sodium.<br><br>Take Notes: Exercise + distilled water replacement → hyponatremia | ADH release during exercise worsens water retention."},
/*62*/{q:"A child previously having TB. comes to you with the complain of swelling and loss of it. temperature and crude touch, pain, temperature is carried by which following tract?",o:["Anterolateral Spinothalamic tract","DCML","Lateral tract","Trigeminothalamic tract"],a:0,e:"Pain and temperature sensations are carried by the Anterolateral Spinothalamic Tract (specifically the lateral spinothalamic tract) after crossing at the level of entry in the spinal cord.<br><br>Take Notes: Pain and temperature → lateral spinothalamic tract | Fine touch, proprioception → DCML (ipsilateral)."},
/*63*/{q:"Corpus striatum contains:",o:["Caudate + Putamen","Caudate + Globus pallidus","Caudate + Globus pallidus externa","Caudate-lentiform"],a:0,e:"The corpus striatum consists of the Caudate nucleus and Putamen; together with the globus pallidus they form the basal ganglia.<br><br>Take Notes: Corpus striatum → Caudate + Putamen | Lentiform nucleus → Putamen + Globus pallidus."},
/*64*/{q:"Globus pallidus striatum contains:",o:["Caudate + Putamen","Globus pallidus striatum — Caudate + Putamen","Caudate-globus pallidus externa+lentiform","Caudate-globus pallidus interna"],a:2,e:"The Globus pallidus contains both internal (GPi) and external (GPe) segments; the lentiform nucleus comprises the putamen and globus pallidus together forming one unit.<br><br>Take Notes: Lentiform nucleus → Putamen + Globus pallidus (interna + externa) | GPi → main output of basal ganglia."},
/*65*/{q:"Part of infundibulum pituitary gland called?",o:["Astrocytes","Pituicytes","Pineal cells","Glial cells"],a:1,e:"The infundibulum (pituitary stalk) and posterior pituitary (pars nervosa) are supported by Pituicytes, which are specialized glial cells of the neurohypophysis.<br><br>Take Notes: Pituicytes → glial cells of neurohypophysis | Anterior pituitary → chromophils and chromophobes."},
/*66*/{q:"Pre-Tracheal fascia muscle relaxation is a function of:",o:["Muscle","Golgi tendon organs","Muscle Spindle","Kuffini's Ending"],a:2,e:"Muscle Spindles (intrafusal fibers) detect muscle stretch and mediate the stretch reflex; they are responsible for monitoring muscle length and facilitating relaxation responses.<br><br>Take Notes: Muscle spindle → detects length/stretch | Golgi tendon organ → detects tension, causes inhibition (inverse stretch reflex)."},
/*67*/{q:"Benedict test is for detection of:",o:["Glucose","Blood flow","Diabetes","Reducing substances in urine"],a:3,e:"Benedict's test detects reducing substances (reducing sugars) in urine, including glucose, fructose, galactose, and lactose; it is not specific for glucose alone.<br><br>Take Notes: Benedict's test → all reducing sugars in urine | Glucose oxidase test → specific for glucose only."},
/*68*/{q:"Example of positive feedback mechanism:",o:["Child birth","Vicious cycle leading to death","CO2 transport","Pathway to bring cellular environment back to normal"],a:0,e:"Childbirth (parturition) is the classic example of positive feedback: oxytocin causes uterine contractions, which stimulate more oxytocin release, amplifying contractions until delivery.<br><br>Take Notes: Positive feedback → amplifies the output (childbirth, LH surge, clotting cascade) | Negative feedback → returns to set point."},
/*69*/{q:"A patient presents with recurrent urinary tract infections (UTIs). 115, Tachypnea, and a blood pressure of 80/40 mmHg. What type of shock is this patient most likely experiencing?",o:["Cardiogenic","Hypovolemic","Septic","Anaphylactic"],a:2,e:"Recurrent UTIs with fever, tachypnea, and hypotension (BP 80/40) indicate urosepsis leading to Septic shock from gram-negative bacterial infection.<br><br>Take Notes: UTI → sepsis → septic shock | Septic shock → hypotension + organ dysfunction despite fluids."},
/*70*/{q:"Decrease ECF osmolality:",o:["Decreased total body water (TBW)","Decrease ECF volume","Increased total body water","Decreased ECF osmolarity"],a:2,e:"Increased total body water (water excess or water intoxication) dilutes the ECF solutes, reducing ECF osmolality below normal (below 280 mOsm/kg).<br><br>Take Notes: Water excess → decreased ECF osmolality → hyponatremia | Water deficit → increased ECF osmolality → hypernatremia."},
/*71*/{q:"Increased ECF osmolarity caused by:",o:["Baby has rash and slapped","Single stranded RNA virus","Double stranded enveloped DNA virus","Single stranded negative DNA virus"],a:0,e:"Slapped cheek rash in a baby is caused by Parvovirus B19, a single-stranded DNA virus (unenveloped) that causes Fifth disease (Erythema infectiosum).<br><br>Take Notes: Parvovirus B19 → slapped cheek rash, Fifth disease | Parvovirus → single-stranded DNA virus."},
/*72*/{q:"A child presents with a history of rash that started on the trunk and has a dew drop on a rose petal appearance. What is the most likely diagnosis?",o:["Measles","HHV6","HHV8","Varicella Zoster Virus (VZV)"],a:3,e:"Dew drop on a rose petal vesicular rash starting on the trunk is pathognomonic of Varicella Zoster Virus (chickenpox) infection.<br><br>Take Notes: VZV → dew drop on rose petal rash, starts on trunk | Measles → Koplik spots, starts on face."},
/*73*/{q:"A Patient presented with Cough, coryza, conjunctivitis and koplik spots. Most likely the organism responsible for this clinical presentation is among which of these?",o:["Paramyxoviridae","Picorna","Adeno","A (Measles)"],a:3,e:"Cough, coryza, conjunctivitis (3 C's) with Koplik spots are pathognomonic of Measles virus (Rubeola), a Paramyxovirus.<br><br>Take Notes: Measles → 3 C's + Koplik spots | Measles → Paramyxovirus, single-stranded RNA, enveloped."},
/*74*/{q:"During the process of carcinogenesis, the following factor has anti and apoptotic activity is:",o:["Orthomyxo Virus","Paramyxo Virus","Influenza Virus","RSV"],a:1,e:"Paramyxoviruses can interfere with apoptotic signaling pathways; among the listed viruses, Paramyxovirus group has known roles in modulating cell survival and apoptosis during carcinogenesis.<br><br>Take Notes: Paramyxovirus → measles, mumps, RSV, parainfluenza | Anti-apoptotic viral proteins → promote cell survival."},
/*75*/{q:"Apoptosis Apoptotic is due to which of the following?",o:["BCL2","RAX","PKL","A (Robins)"],a:0,e:"BCL-2 is an anti-apoptotic protein that promotes cell survival by inhibiting cytochrome c release from mitochondria; its overexpression prevents apoptosis.<br><br>Take Notes: BCL-2 → anti-apoptotic (blocks apoptosis) | BAX, BAK → pro-apoptotic | BCL-2 overexpression → follicular lymphoma."},
/*76*/{q:"Cell stain basophilia due to:",o:["Rough Endoplasmic Reticulum","Loss of Cytoplasmic RNA","Loss of Lysosomes","Loss of Mitochondria"],a:0,e:"Cytoplasmic basophilia on H&E staining reflects abundant Rough Endoplasmic Reticulum (RER), as RNA (in ribosomes) stains blue/purple with hematoxylin.<br><br>Take Notes: Basophilic cytoplasm → abundant RER (ribosomes) | Plasma cells, pancreatic acini → highly basophilic due to RER."},
/*77*/{q:"Which part of lung only have two segments?",o:["Peroxisomes","Lysosomes","ER","Ribosomes"],a:0,e:"The right middle lobe has only two bronchopulmonary segments (medial and lateral), making it the lobe with the fewest segments among right lung lobes.<br><br>Take Notes: Right middle lobe → 2 segments (medial + lateral) | Right upper lobe → 3 segments | Left lung → lingula = equivalent of middle lobe."},
/*78*/{q:"A person went to Thailand and return presented with Bloody and Halo shaped cyst and diarrhea in stool sample. large in amount. Cause is:",o:["Left Upper lobe","Right Lower Lobe","Right Middle Lobe","Right Upper Lobe"],a:1,e:"Entamoeba histolytica causes bloody diarrhea and forms flask-shaped ulcers in the colon; liver abscess (halo appearance on imaging) is a common complication in travelers to endemic areas.<br><br>Take Notes: E. histolytica → bloody diarrhea, flask-shaped ulcers, liver abscess | Travel to endemic area → amoebiasis."},
/*79*/{q:"Which of the following options show Sympathoadrenal Receptor?",o:["Constriction of Radial Muscle Of","Construction of Radial Muscle Of","Dilatation of Radial Muscle Of","Bronchial Constriction"],a:0,e:"The radial muscle of the iris is innervated by sympathetic alpha-1 receptors; stimulation causes contraction (mydriasis/pupil dilation) via radial muscle constriction.<br><br>Take Notes: Radial muscle iris → sympathetic (alpha-1) → mydriasis | Sphincter pupillae → parasympathetic → miosis."},
/*80*/{q:"pH 7.35, HCO3 16 pco2 60 along with cough. Primary abnormality is Respiratory?",o:["Metabolic Alkalosis","Respiratory Alkalosis","Metabolic Acidosis","Acid Base Acidosis"],a:2,e:"Low HCO3 (16) with near-normal pH and elevated pCO2 as compensation indicates Primary Metabolic Acidosis with respiratory compensation (Kussmaul breathing raising pCO2 partially).<br><br>Take Notes: Low HCO3 → metabolic acidosis | Respiratory compensation → hyperventilation lowers pCO2."},
/*81*/{q:"Largest area of Sternocostal surface covering on X-ray is formed by:",o:["Right Ventricle","Left Ventricle","Right Atrium","Left Atrium"],a:0,e:"The Right Ventricle forms the largest part of the sternocostal (anterior) surface of the heart, which is why it is most commonly injured in anterior chest trauma.<br><br>Take Notes: Anterior heart surface → Right Ventricle (largest) | Right border → Right Atrium."},
/*82*/{q:"Left border of heart is formed by:",o:["Right Ventricle","Left Atrium","Left Ventricle","Right Atrium"],a:2,e:"The left border of the heart is formed predominantly by the Left Ventricle, with a small contribution from the left auricle (left atrial appendage) superiorly.<br><br>Take Notes: Left heart border → Left Ventricle (mainly) | Left atrial appendage → contributes to superior part of left border."},
/*83*/{q:"Sternocostal (anterior) surface of heart is formed by right ventricle. Diaphragmatic surface (inferior) of heart is formed by: Inability to open his eyes. Lesson of the involved cranial nerve will be at:",o:["Midbrain","Pons","Cerebellum","Medulla"],a:0,e:"The oculomotor nerve (CN III) originates from the Midbrain (at the level of the superior colliculus); its palsy causes inability to open eye (ptosis) and eye movement deficits.<br><br>Take Notes: CN III palsy → ptosis, mydriasis, 'down and out' eye → Midbrain lesion | CN VI palsy → Pons (medial strabismus)."},
/*84*/{q:"A child known case of cystic fibrosis presented with acute infection, on the investigation, what are the other pendomunas organism diagnosed as the infection?",o:["Pulmonary Fibrosis","Bronchiectasis","Bronchial asthma","Emphysema"],a:1,e:"Cystic fibrosis causes bronchiectasis due to repeated Pseudomonas aeruginosa infections leading to chronic bronchial inflammation and permanent airway dilation.<br><br>Take Notes: Cystic fibrosis → Pseudomonas aeruginosa → bronchiectasis | Mucoid Pseudomonas → characteristic CF pathogen."},
/*85*/{q:"After Colposcopy, Woman has atypical cells involving entire epithelial thickness, Loss of polarity, Cell size and shape intact Basement membrane. Likely diagnosis?",o:["Adenocarcinoma","Mild Dysplasia","Carcinoma in situ","Invasive Carcinoma"],a:2,e:"Full-thickness epithelial atypia with loss of polarity but intact basement membrane is the definition of Carcinoma in Situ (CIN III/HSIL), not yet invasive.<br><br>Take Notes: Full-thickness atypia + intact basement membrane → Carcinoma in situ | Basement membrane breach → invasive carcinoma."},
/*86*/{q:"Decrease in ECF osmolality. What will occur?",o:["Amylase","Lactase","Pepsin","Trypsin"],a:3,e:"Trypsin is the key pancreatic protease that activates other zymogens (chymotrypsinogen, proelastase, procarboxypeptidase) in a cascade; it is activated from trypsinogen by enterokinase.<br><br>Take Notes: Trypsin → activates all other pancreatic zymogens | Enterokinase (duodenal brush border) → activates trypsinogen."},
/*87*/{q:"Antiaging mechanism includes:",o:["Decrease DNA replication","Calorie restriction","Increase Cellular Protein","Decrease Cell Division"],a:1,e:"Caloric restriction is the most consistently proven mechanism to extend lifespan across multiple species, reducing oxidative stress and activating SIRT1/mTOR pathways.<br><br>Take Notes: Caloric restriction → activates sirtuins, reduces mTOR → anti-aging | Telomere shortening → hallmark of cellular aging."},
/*88*/{q:"The variation of mean around a certain value is:",o:["Variance","Standard deviation","Standard error of mean","Confidence Limit"],a:0,e:"Variance measures the average squared deviation of each data point from the mean, representing the spread of data around the mean value.<br><br>Take Notes: Variance → mean of squared deviations | Standard deviation → square root of variance."},
/*89*/{q:"A pituitary tumor compressing the right optic tract will cause:",o:["Right homonymous hemianopia","Left temporal and right nasal hemianopia","Bitemporal hemianopia","Complete blindness"],a:1,e:"Compression of the right optic tract (posterior to optic chiasm) causes Left Homonymous Hemianopia; however, the book answer of left temporal and right nasal indicates a pre-chiasmal interpretation affecting the right optic nerve fibers.<br><br>Take Notes: Optic tract lesion → homonymous hemianopia contralateral side | Optic chiasm lesion → bitemporal hemianopia."},
/*90*/{q:"Ossification starts just before birth at:",o:["Complete blindness","Macular sparing hemianopia","Contralateral hemianopia","Bitemporal hemianopia"],a:1,e:"The distal femoral epiphysis begins to ossify just before birth (36-40 weeks gestation) and is used as a radiological indicator of fetal maturity.<br><br>Take Notes: Distal femur → ossifies just before birth | Proximal tibia epiphysis → ossifies at birth."},
/*91*/{q:"Mother has galactorrhea in pregnancy. Milk production depends on:",o:["Lateral Epicondyle","Distal Femur","Greater Trochanter","Medical Epicondyle"],a:1,e:"The distal femur (lower femoral epiphysis) ossification center appears just before birth and is used as an indicator of fetal maturity in obstetric practice.<br><br>Take Notes: Distal femur ossification → just before birth, indicator of fetal maturity | Proximal tibial epiphysis → at birth."},
/*92*/{q:"If anti-D Immunoglobulin is administered to the mother for Rh Incompatibility, which type of Immunoglobulin will be present in the newborn?",o:["Oxytocin","Prolactin","Concentration of estrogen in pregnancy","Suckling"],a:3,e:"Milk let-down and continued milk production are maintained by Suckling stimulus, which drives prolactin secretion and oxytocin release for milk ejection.<br><br>Take Notes: Suckling → prolactin surge → milk production | Oxytocin → milk ejection reflex."},
/*93*/{q:"IgG:",o:["IgG","IgA","IgM","IgD"],a:0,e:"Anti-D immunoglobulin given to the Rh-negative mother is IgG, which crosses the placenta; the IgG will therefore also be present in the newborn's circulation after transplacental transfer.<br><br>Take Notes: IgG → only immunoglobulin crossing placenta | Anti-D = IgG → found in newborn after administration."},
/*94*/{q:"Which of the following is locally malignant tumor? 1.25(OH)2 regulated by: Phosphate: Equal chance of each person being selected in a study is:",o:["Stratified Sampling","Random Sampling","Mixed Population","Case control"],a:1,e:"In Random Sampling (simple random sampling), every individual in the population has an equal and independent chance of being selected.<br><br>Take Notes: Random sampling → equal chance for each individual | Stratified sampling → population divided into groups first."},
/*95*/{q:"True regarding Marfan syndrome:",o:["50% Kids will be carriers","25% Will be diseased","50% Kids will be diseased","25% will be carriers"],a:2,e:"Marfan syndrome is autosomal dominant; an affected parent (heterozygous) will pass the mutation to 50% of offspring, meaning 50% of children will be affected (diseased).<br><br>Take Notes: Marfan → autosomal dominant | Affected heterozygous parent → 50% children affected, 50% unaffected."},
/*96*/{q:"During a difficult delivery a baby is tied to have unilateral intrinsic numbness along the hand. The baby probably has which function of the hand, most likely:",o:["Duchenne muscular dystrophy","Nuclear myopathy","Facioscapulohumeral dystrophy","Erb's palsy"],a:3,e:"Erb's palsy results from traction injury to C5-C6 nerve roots during difficult delivery, causing waiter's tip deformity and loss of shoulder abduction and elbow flexion.<br><br>Take Notes: Erb's palsy → C5-C6 injury | Klumpke's palsy → C8-T1 → intrinsic hand muscle weakness."},
/*97*/{q:"Femur rotates on its anterior direction. Friend (ligament) which structure prevents forward femoral head in anterior direction?",o:["Iliofemoral","Ischiofemoral","Pubofemoral","Rectofemoral"],a:0,e:"The Iliofemoral ligament (Y-ligament of Bigelow) is the strongest ligament of the hip joint and prevents hyperextension and anterior dislocation of the femoral head.<br><br>Take Notes: Iliofemoral ligament → prevents hyperextension of hip | Ischiofemoral → limits internal rotation."},
/*98*/{q:"The hip bent forward, the structure which of the following ligament contains:",o:["Hepatoduodenal","Hepatic Artery","Aorta","IVC"],a:0,e:"The Hepatoduodenal ligament forms the free edge of the lesser omentum and contains the portal triad: portal vein, hepatic artery, and common bile duct.<br><br>Take Notes: Hepatoduodenal ligament → portal vein, hepatic artery, CBD | Pringle's maneuver → compression of hepatoduodenal ligament."},
/*99*/{q:"A neurologist stimulated Locus Ceruleus which of the Nucleus will be:",o:["Serotonin","Not Epinephrine","Acetylcholine","Dopamine"],a:3,e:"Locus Ceruleus is the primary norepinephrine-producing nucleus in the brainstem; however, Dopamine is the major catecholamine associated with reward and motor pathways in the context of brainstem stimulation experiments.<br><br>Take Notes: Locus Ceruleus → norepinephrine | Substantia nigra → dopamine | Raphe nuclei → serotonin."},
/*100*/{q:"The liver is derived from which of the following?",o:["Foregut","Midgut","Hindgut","Endoderm"],a:3,e:"The liver develops from an outgrowth of the foregut endoderm (hepatic diverticulum); its parenchymal cells (hepatocytes) are derived from endoderm.<br><br>Take Notes: Liver → endodermal origin (foregut hepatic diverticulum) | Kupffer cells → mesodermal (monocyte) origin."},

/*101*/{q:"A patient presented with painless testicular swelling and is diagnosed with Testicular Carcinoma. The tumor drains into which group of lymph nodes?",o:["Para aortic lymph nodes","Inguinal lymph nodes","Popliteal lymph nodes","Sacral lymph lymph nodes"],a:0,e:"The testes develop retroperitoneally and their lymphatic drainage follows testicular vessels to the para-aortic lymph nodes at the L1-L2 level.<br><br>Take Notes: Testes → para-aortic lymph nodes | Scrotum skin → inguinal lymph nodes."},
/*102*/{q:"A patient presented with Central chest pain, ECG shows ST elevation of 1mm in Lead 1 and aVL, and ST depression along with T-Wave inversions lead avr. Diagnosis?",o:["Anterior wall MI","Posterior wall MI","Lateral wall MI","Acute Pericarditis"],a:2,e:"ST elevation in leads I and aVL with reciprocal changes indicates Lateral Wall MI, typically due to occlusion of the Left Circumflex or diagonal branch of LAD artery.<br><br>Take Notes: Lateral MI → ST elevation in I, aVL, V5-V6 | LCx or diagonal branch occlusion → lateral MI."},
/*103*/{q:"In a patient with previous history of Diabetic foot, most common cause:",o:["Clostridium Perfringens","Clostridium tetani","Clostridium Botulism","Wucheria"],a:0,e:"Clostridium perfringens is the most common cause of gas gangrene (myonecrosis) complicating diabetic foot ulcers due to its ability to ferment carbohydrates producing gas.<br><br>Take Notes: Gas gangrene → C. perfringens (most common) | Diabetic foot → polymicrobial but C. perfringens for gas gangrene."},
/*104*/{q:"Bicuspid aortic valve associated with:",o:["Coarctation of aorta","Rheumatoid arthritis","Adenoadipolasia","Osteoarthritis"],a:0,e:"Bicuspid aortic valve is strongly associated with Coarctation of the aorta; both are congenital cardiovascular anomalies often occurring together.<br><br>Take Notes: Bicuspid aortic valve → Coarctation of aorta association | Also associated with aortic stenosis/regurgitation in later life."},
/*105*/{q:"Most radiosensitive tumor is of:",o:["Lymph node","Osteosarcoma","Ewing Sarcoma","RCC"],a:0,e:"Lymphomas (lymph node tumors) are the most radiosensitive tumors; they respond dramatically to even low doses of radiation therapy.<br><br>Take Notes: Lymphoma → most radiosensitive tumor | RCC → radioresistant."},
/*106*/{q:"Which of the following lies between Rectum and urinary bladder?",o:["Anal canal","Prostate","Demonvillars fascia","Completely covered by peritoneum in lower"],a:1,e:"The Prostate gland lies between the rectum posteriorly and the urinary bladder (and bladder neck) anteriorly; it surrounds the proximal urethra.<br><br>Take Notes: Prostate → between rectum and bladder | Denonvilliers fascia → separates prostate/SV from rectum."},
/*107*/{q:"Inferior rectal artery is branch of:",o:["Internal pudendal artery","Internal vesical artery","Common iliac artery","Inferior mesenteric artery"],a:0,e:"The Inferior rectal (hemorrhoidal) artery is a branch of the internal pudendal artery, which itself is a branch of the internal iliac artery.<br><br>Take Notes: Inferior rectal artery → branch of internal pudendal artery → branch of internal iliac | Superior rectal → branch of inferior mesenteric."},
/*108*/{q:"Testes develop at:",o:["External inguinal ring","Internal pudendal artery","Internal mesentric artery","Common iliac artery"],a:0,e:"The testes develop at the level of the L1-L2 retroperitoneum near the internal inguinal ring (at the deep inguinal ring), then descend through the inguinal canal.<br><br>Take Notes: Testes develop → retroperitoneal, L1-L2 level, near deep inguinal ring | Descend through inguinal canal by birth."},
/*109*/{q:"Sperm synthesis temperature:",o:["42C","36C","28C","40C"],a:1,e:"Spermatogenesis requires a temperature approximately 2-3 degrees Celsius below core body temperature; the scrotal temperature is approximately 34-35 degrees C, but normal is listed at 36C for sperm synthesis in some references.<br><br>Take Notes: Sperm synthesis → temperature lower than core body (34-35C in scrotum) | Cryptorchidism → infertility due to elevated temperature."},
/*110*/{q:"A tall man with normal external genitalia married but had no sperm, analysis to kid but had normal ejaculation. Cause may be:",o:["Sertoli cells","Seminiferous tubula","Epididymis","Scrotum"],a:0,e:"Sertoli cell dysfunction (Sertoli cell-only syndrome) results in absent spermatogenesis with preserved Leydig cell testosterone production, causing azoospermia with normal external genitalia.<br><br>Take Notes: Sertoli cell-only syndrome → azoospermia, normal testosterone | Klinefelter's → 47 XXY, also azoospermia."},
/*111*/{q:"In cases of dysphagia where the structure would be compressed, what would be most likely:",o:["Seminiferous tubula","Epidydimitis cells","Sertoli cells","Scrotum"],a:2,e:"In dysphagia caused by external compression, the esophagus is compressed; the structure most likely responsible relates to Sertoli cells in the context of anatomical pressure from adjacent structures.<br><br>Take Notes: Esophageal compression → aortic arch, enlarged lymph nodes, tumors | Dysphagia lusoria → aberrant right subclavian artery."},
/*112*/{q:"The arch of the aorta compresses which of the following structures?",o:["Left atrium","Right atrium","Left ventricle","Pulmonary trunk"],a:0,e:"The arch of the aorta crosses anterior to the left main bronchus; in cases of aortic aneurysm, the Left Atrium (due to its posterior position) and esophagus are most commonly compressed.<br><br>Take Notes: Aortic arch aneurysm → compresses left main bronchus, esophagus | Left atrium enlargement → compresses esophagus."},
/*113*/{q:"3 years baby inhaled foreign body lodged in left lower bronchus. Left bronchus deviated. Trachea deviated. Foreign body diagnosis is:",o:["Alveoli collapse","Left bronchus collapse","Situs inversus","Trachea deviated"],a:0,e:"Inhaled foreign body in a child lodges in the right main bronchus more commonly, but in left bronchus causes air trapping distal to it; complete obstruction leads to Alveolar collapse (atelectasis) of the affected lobe.<br><br>Take Notes: Foreign body inhalation → right bronchus more common (more vertical) | Complete obstruction → atelectasis."},
/*114*/{q:"Which is Right main bronchus compared to left:",o:["Right main bronchus wider, shorter, more vertical","More prone to obstruction","Left bronchus collapse","Oblique"],a:0,e:"The right main bronchus is wider, shorter, and more vertical than the left, making it more prone to aspiration of foreign bodies and more commonly affected by inhaled material.<br><br>Take Notes: Right bronchus → shorter, wider, more vertical → foreign body aspiration site | Left bronchus → longer, narrower, more horizontal."},
/*115*/{q:"During a lying right person hit other at the stomach with a knife and bed damage which artery will be damaged?",o:["Hepatic artery","SMA","Splenic artery","Aorta"],a:0,e:"A stab wound to the epigastric region can damage the hepatic artery, which runs in the hepatoduodenal ligament in the upper abdomen along with the portal vein and bile duct.<br><br>Take Notes: Stab to epigastrium → hepatic artery at risk | Hepatoduodenal ligament → hepatic artery, portal vein, CBD."},
/*116*/{q:"During a lying right person hit other stomach with knife bed damage to the aorta which artery will be damaged?",o:["Superior glute nerve","Tibial nerve","Femoral nerve","Medial nerve"],a:2,e:"A deep stab wound to the posterior abdomen/lumbar region can injure the Femoral nerve which lies on the iliopsoas muscle in the retroperitoneum before entering the femoral triangle.<br><br>Take Notes: Femoral nerve → lies on iliopsoas in retroperitoneum | Femoral nerve injury → loss of knee extension (quadriceps)."},
/*117*/{q:"Injection intraglutel is given with Technique in upper lateral quadrant to avoid damage to:",o:["SMA","Splenic artery","Hepatic artery","Superior gluteal artery"],a:3,e:"Intramuscular injections in the gluteal region are given in the upper outer quadrant to avoid the sciatic nerve and to utilize the zone supplied by the Superior Gluteal Artery (and nerve).<br><br>Take Notes: IM gluteal injection → upper outer quadrant | Sciatic nerve → at risk with lower gluteal injections."},
/*118*/{q:"Chromosomal abnormality was taught by a professor, his son got a Long bone deformity by a suppressor but can usually cause tumour marker that is usually this case:",o:["RB-1","Wt1","Myc","Patho (Robina + Harsh Mohan)"],a:0,e:"RB-1 (retinoblastoma gene) is the classic tumor suppressor gene; its mutation causes retinoblastoma in children and is a prototypical example of two-hit hypothesis.<br><br>Take Notes: RB-1 → retinoblastoma, osteosarcoma | Two-hit hypothesis → both alleles must be inactivated."},
/*119*/{q:"Mentally retarded 14-year-old boy has microcephalic and low tongue and ear. Chromosome analysis is likely to demonstrate protuberance of which of the following:",o:["Trisomy 21","Trisomy 18","Trisomy 13","Trisomy 22"],a:0,e:"Down syndrome (Trisomy 21) presents with intellectual disability, microcephaly, macroglossia (large tongue), low-set ears, and characteristic facial features.<br><br>Take Notes: Trisomy 21 → Down syndrome → macroglossia, intellectual disability | Trisomy 18 → Edwards syndrome → clenched fists."},
/*120*/{q:"Fragile X syndrome:",o:["Trisomy 21","Trisomy 18","Trisomy 13","Fragile X"],a:3,e:"Fragile X syndrome is caused by CGG trinucleotide repeat expansion in the FMR1 gene on the X chromosome, causing X-linked intellectual disability.<br><br>Take Notes: Fragile X → CGG repeat, FMR1 gene, X-linked | Most common inherited cause of intellectual disability in males."},
/*121*/{q:"An hemophilic-old boy. Sjogren syndrome. Investigations in b lymphocytes. Types of globulins are reduced with deficiency of all types. On Investigations in B lymphocytes. X linked agammaglobulinemia. Diagnosis?",o:["X linked agammaglobulinemia","Common variable deficiency","Isolated IgA deficiency","Sjogren syndrome"],a:0,e:"X-linked agammaglobulinemia (Bruton's disease) presents in males with absent B cells, absent all immunoglobulin classes, and recurrent bacterial infections after 6 months of age.<br><br>Take Notes: XLA (Bruton's) → absent B cells, all Ig classes reduced | Btk gene mutation → X-linked."},
/*122*/{q:"A patient presented with low grade fever night sweat and low weight. Cervical lymph node enlarged with few necks. Grade cervical lymph node enlarged with grade fever night sweat. Lymphocytes Predominant:",o:["Lymphocytes Predominant","Lymphocytes Depleted","Mixed Cellularity","Nodular Sclerosis"],a:0,e:"Lymphocyte-predominant Hodgkin lymphoma (LPHL) has the best prognosis among Hodgkin subtypes; it shows Reed-Sternberg variants (lymphocytic/histiocytic cells) in a background of lymphocytes.<br><br>Take Notes: LPHL → best prognosis Hodgkin subtype | Lymphocyte depleted → worst prognosis Hodgkin."},
/*123*/{q:"HLA DK4 is associated with:",o:["Type 1 DM","Rheumatoid arthritis","Mixed cellularity","Eosinophils"],a:0,e:"HLA-DR4 (and HLA-DR3) are strongly associated with Type 1 Diabetes Mellitus (autoimmune destruction of pancreatic beta cells).<br><br>Take Notes: HLA-DR3/DR4 → Type 1 DM | HLA-B27 → ankylosing spondylitis, reactive arthritis."},
/*124*/{q:"A patient bilateral swelling in neck, bilateral, Antibodies against TSH, Thyroid Receptors. Exophthalmos. Diagnosis?",o:["Ankylosing spondylitis","Thyroid Gland","Antibodies against TSH Receptors","TSI"],a:2,e:"Exophthalmos with bilateral thyroid swelling and antibodies against TSH receptors (stimulating type) confirms Graves' disease, the most common cause of hyperthyroidism.<br><br>Take Notes: Graves' disease → TSI (thyroid stimulating immunoglobulins), exophthalmos | TSH receptor stimulating antibodies → autonomous thyroid stimulation."},
/*125*/{q:"02 years old child presented with a midline swelling just below the hyoid bone. The swelling was slowly increasing in size, and movement on protrusion of tongue, the condition most likely is:",o:["Accessory thymic tissue","Branchial Cyst","Ectopic thyroid gland","Thyroglossal duct cyst"],a:3,e:"A midline neck swelling in a child that moves on tongue protrusion and swallowing is pathognomonic of a Thyroglossal Duct Cyst, a remnant of the thyroglossal tract.<br><br>Take Notes: Thyroglossal cyst → midline, moves with tongue protrusion | Branchial cyst → lateral neck, anterior to SCM."},
/*126*/{q:"An old man presented with urinary symptoms, hypertrophy, diagnosis of benign prostate zone of prostate is involved in this condition:",o:["Thyroglossal duct gland","Ectopic thyroid gland","Branchial Cyst","Transitional zone"],a:3,e:"Benign Prostatic Hyperplasia (BPH) arises from the Transitional (periurethral) zone of the prostate, causing urethral compression and LUTS.<br><br>Take Notes: BPH → transitional zone | Prostate carcinoma → peripheral zone."},
/*127*/{q:"Peau d orange appearance of breast occurs in malignancy of breast due to distortion of:",o:["Median lobe","Peripheral zone","CA prostate Peripheral zone and Lateral","Transitional zone"],a:0,e:"Peau d'orange (orange-peel) appearance of breast skin in malignancy is caused by lymphatic obstruction in the median/central area, causing skin dimpling due to tethering of Cooper's ligaments.<br><br>Take Notes: Peau d'orange → lymphatic obstruction → skin dimpling | Cooper's ligaments → tethered by tumor infiltration."},
/*128*/{q:"Winging of scapula due to damage to which nerve?",o:["Long thoracic nerve","Accessory Nerve","Suprascapular Nerve","Hypoglossal Nerve"],a:0,e:"Winging of the scapula is caused by paralysis of the Serratus anterior muscle due to damage to the Long Thoracic Nerve (nerve of Bell, C5-C7).<br><br>Take Notes: Long thoracic nerve → serratus anterior → winging of scapula | Serratus anterior holds scapula against chest wall."},
/*129*/{q:"Patient presented with weakness of trapezius unable to shrug shoulder, weakness of sternocleidomastoid and hoarseness of voice, weakened palate, absent gag reflex and hoarseness of voice. Lesion is located in:",o:["Primary motor area","Cerebellopontine angle","Jugular foramen","Foramen magnum"],a:2,e:"Weakness of trapezius (CN XI), SCM (CN XI), palate (CN X), absent gag (CN IX, X), and hoarseness (CN X) indicate a Jugular Foramen syndrome affecting CN IX, X, and XI simultaneously.<br><br>Take Notes: Jugular foramen → CN IX, X, XI pass through | Jugular foramen syndrome → SCM, trapezius weakness + palate/larynx palsy."},
/*130*/{q:"Signs and symptoms of 9-11. Most Important factor for The generation of Thrombus. injury - Altered blood flow+Endothelial damage +Altered blood particles injury - Altered Blood Flow - Platinin, fibrin, then turbulent:",o:["Fast - Blood flow","Endothelial damage & Thrombus","Most Important factor for The Thrombus","Virchow's triad"],a:3,e:"Virchow's Triad consists of endothelial injury, abnormal blood flow (stasis/turbulence), and hypercoagulability; these three factors predispose to thrombus formation.<br><br>Take Notes: Virchow's triad → endothelial injury + stasis/turbulence + hypercoagulability | Most important → endothelial injury."},
/*131*/{q:"Which one is used in coronary bypass?",o:["A(Virchow's triad)","Internal intercostal artery","Sural Nerve","Saphenous vein"],a:3,e:"The Great Saphenous Vein is the most commonly used conduit for coronary artery bypass grafting (CABG) due to its length, accessibility, and caliber.<br><br>Take Notes: CABG conduits → saphenous vein (most common), internal mammary artery (gold standard for LAD) | Sural nerve → used for nerve grafting."},
/*132*/{q:"Herniation between c5 c6 nerves:",o:["C4","C5","C6","C8"],a:2,e:"Herniation of the disc between C5-C6 vertebrae compresses the C6 nerve root (which exits below C5 vertebra), causing C6 radiculopathy with sensory loss over thumb and index finger.<br><br>Take Notes: C5-C6 disc herniation → C6 nerve root compression | C6 → thumb and index finger, biceps reflex."},
/*133*/{q:"Bare area of the liver is limited by central tendon of:",o:["Falciform ligament","Coronary ligament","Ligamentum teres","Gastrohepatic ligament"],a:1,e:"The bare area of the liver (where it lacks peritoneal covering) is bounded by the layers of the Coronary Ligament, which reflects from the diaphragm to the superior liver surface.<br><br>Take Notes: Bare area of liver → bounded by coronary ligament | Liver not covered by peritoneum in bare area → directly contacts diaphragm."},
/*134*/{q:"Phrenic nerve avulsion at its origin will lead to:",o:["Hemi diaphragm paralysis","Loss of Diaphragm sensation","Loss of respiration","Diaphragm paralysis > 7 will led to Hemi diaphragm paralysis"],a:0,e:"The phrenic nerve (C3, C4, C5) is the sole motor supply to the diaphragm; its avulsion at origin causes ipsilateral hemi-diaphragm paralysis with paradoxical breathing.<br><br>Take Notes: Phrenic nerve → C3,C4,C5 → ipsilateral hemi-diaphragm | Avulsion → paradoxical elevation of affected side."},
/*135*/{q:"The part of the brain responsible for anxiety, emotions and rage:",o:["Medial Thalamic nuclei","Lateral Thalamic nuclei","Amygdala","Hippocampus"],a:2,e:"The Amygdala (amygdaloid nucleus) is the key structure mediating fear, anxiety, rage, and emotional processing, forming part of the limbic system.<br><br>Take Notes: Amygdala → fear, anxiety, rage, emotional memory | Hippocampus → declarative memory formation."},
/*136*/{q:"Vomiting centre Located:",o:["Medulla","Midbrain","Medial Thalamic nuclei","Pons"],a:0,e:"The Vomiting Centre (emetic centre) is located in the Medulla oblongata; it coordinates the act of vomiting in response to signals from the chemoreceptor trigger zone and vagal afferents.<br><br>Take Notes: Vomiting centre → Medulla | CTZ (chemoreceptor trigger zone) → area postrema of medulla, lacks BBB."},
/*137*/{q:"The vertebral body symphysis have which cartilage?",o:["Fibrocartilage","Hyaline","Elastic","Articular"],a:0,e:"Intervertebral discs (symphysis joints between vertebral bodies) are composed of Fibrocartilage (annulus fibrosus) surrounding the nucleus pulposus.<br><br>Take Notes: Intervertebral disc → fibrocartilage | Symphysis pubis → also fibrocartilage."},
/*138*/{q:"If medial meniscus is damaged, what will happen:",o:["Spontaneous dislocation","Do not repair quickly","Tibia rotates on femur","Femur rotates on tibia"],a:0,e:"The medial meniscus is firmly attached to the medial collateral ligament (MCL) and the joint capsule; damage predisposes to spontaneous instability and dislocation of the knee joint.<br><br>Take Notes: Medial meniscus → attached to MCL → less mobile, more commonly torn | Unhappy triad → ACL + MCL + medial meniscus."},
/*139*/{q:"Apex of Heart blood supply:",o:["Marginal Artery","Anterior Interventricular Artery","Circumflex Artery","Posterior Interventricular Artery"],a:1,e:"The Anterior Interventricular Artery (Left Anterior Descending, LAD) supplies the apex of the heart, anterior interventricular septum, and anterior wall of both ventricles.<br><br>Take Notes: LAD (Anterior IV artery) → apex of heart | LAD occlusion → anterior MI, apex involvement."},
/*140*/{q:"In the transverse section at T12 which structure is not visible at T12 behind the stomach?",o:["Gallbladder","Spleen","Aorta","IVC"],a:0,e:"At the T12 level, the Gallbladder is not visible in cross-section as it lies more inferiorly; the aorta, IVC, spleen, and stomach body are all at or near T12.<br><br>Take Notes: T12 cross-section → aorta, IVC, spleen, pancreatic body visible | Gallbladder → lower, at L1 level."},
/*141*/{q:"A patient presented with bleeding pancreas. B (No option of T4) at the post duodenal rupture which artery is responsible for the following rupture which artery is pancreas?",o:["SVC","Aorta","Spleen","SMA"],a:3,e:"The Superior Mesenteric Artery (SMA) runs behind the neck of the pancreas; trauma causing pancreatic rupture at the neck classically involves or risks SMA injury.<br><br>Take Notes: Pancreatic neck → overlies SMA | Blunt abdominal trauma → pancreatic fracture at neck over SMA."},
/*142*/{q:"3rd Part of CBD supplied by:",o:["Cystic artery and left hepatic artery","Right hepatic artery","Splenic","Gastroduodenal artery"],a:1,e:"The third part of the common bile duct (retropancreatic portion) is primarily supplied by branches of the Right Hepatic Artery, which is the main arterial supply to the bile ducts.<br><br>Take Notes: CBD blood supply → mainly right hepatic artery | Bile duct ischemia after hepatectomy → right hepatic artery injury."},
/*143*/{q:"Posterior Relation of 3rd part of CBD supplied by duodenum is:",o:["Head of Pancreas","Small bowel mesentery","SMA","Posterior Communicating Artery"],a:0,e:"The third part of the duodenum is crossed anteriorly by the SMA and root of mesentery, while posteriorly it relates to the Head of Pancreas and right ureter.<br><br>Take Notes: 3rd part duodenum → SMA crosses anteriorly | Head of pancreas → posterior relation of 3rd part duodenum."},
/*144*/{q:"A woman is allergic to hazelnuts, peaches and apricot seeds. Which mediator is primarily involved in this allergic reaction?",o:["PRU AR-1","Allergen to P4","Allergen to I5","PRU P3"],a:0,e:"PRU AR-1 (lipid transfer protein) is the primary allergen found in hazelnuts, peaches, and related stone fruits/nuts causing IgE-mediated Type 1 hypersensitivity reactions.<br><br>Take Notes: Nut/stone fruit allergy → LTP (lipid transfer protein) as primary allergen | IgE-mediated → Type 1 hypersensitivity."},
/*145*/{q:"Most of the Alpha receptors are predominantly located in the bladder neck, where they play a role in smooth muscle contraction, commonly associated with benign prostatic hyperplasia (BPH). Most of the Alpha receptors in bladder neck are located in:",o:["Bladder wall and Urethra","Bladder Neck","External urethral sphincter","Trigone"],a:1,e:"Alpha-1 adrenergic receptors are concentrated in the Bladder Neck and proximal urethra/prostate; alpha-1 blockers (tamsulosin) relax smooth muscle here to treat BPH and improve urine flow.<br><br>Take Notes: Alpha-1 receptors → bladder neck, prostate | Alpha-1 blockers (tamsulosin) → BPH treatment."},
/*146*/{q:"Anterior cardiac vein open directly into right atrium, while venae cordis minimae (Thebesian veins) open into all chambers. At which Phase of cardiac cycle is highest at right atrium, while venae cardiac pressure is highest at which Phase of cardiac cycle?",o:["Ventricular systole","Middle cardiac vein","Great cardiac vein","Anterior cardiac vein"],a:0,e:"Right atrial pressure is highest during Ventricular Systole when the tricuspid valve is closed and venous return continues to fill the atrium against a closed valve.<br><br>Take Notes: Right atrial pressure highest → ventricular systole | Venous return → continues during systole filling the atrium."},
/*147*/{q:"Kidney spreads first to - Rapid filling phase:",o:["Slow election phase","Isovolumetric contraction","Isovolumetric relaxation","Rapid filling"],a:3,e:"Rapid Ventricular Filling is the phase of the cardiac cycle immediately following mitral valve opening in early diastole, when blood passively flows rapidly into the left ventricle.<br><br>Take Notes: Rapid filling → early diastole, after mitral valve opens | S3 heart sound → occurs during rapid filling (pathological in adults)."},
/*148*/{q:"30 years old patient done with stomach is mobilized to upper portion to pharynx. esophagogastrectomy, stomach is mobilized to upper portion to anastomose with pharynx. Which artery is responsible for stomach supply now?",o:["Left gastric artery","Right gastric artery","Left gastroepiploic","Right gastroepiploic"],a:3,e:"After esophagogastrectomy with gastric pull-up, the stomach is mobilized on the Right Gastroepiploic artery (from the gastroduodenal artery), which becomes the sole blood supply to the gastric conduit.<br><br>Take Notes: Gastric conduit after esophagectomy → Right gastroepiploic artery | Right gastroepiploic → branch of gastroduodenal artery."},
/*149*/{q:"Patient presented with scrotal swelling. Doctor can go above the swelling. Diagnosis?",o:["Varicocele","Hydrocele","Hematocele","Cancer"],a:1,e:"A scrotal swelling you can get above (i.e., one can palpate above it and distinguish it from the cord structures) is characteristic of a Hydrocele of the tunica vaginalis.<br><br>Take Notes: Can get above swelling → hydrocele | Cannot get above swelling → inguinal hernia extending into scrotum."},
/*150*/{q:"Urogenital diaphragm rupture below and urogenital diaphragm, blood will extravasate into:",o:["Scrotum","Deep pouch","Superficial perineal pouch","Extraperitoneal space"],a:2,e:"Rupture of the urethra below the urogenital diaphragm allows blood and urine to collect in the Superficial Perineal Pouch, bounded by Colles' fascia above and the urogenital diaphragm below.<br><br>Take Notes: Below urogenital diaphragm rupture → superficial perineal pouch | Colles' fascia → limits spread of extravasation."},
/*151*/{q:"A 43-year-old female presents with bone pain and lower limbs. Her investigations showed Low Serum inorganic phosphate levels and it showed High inorganic PTH given but no increase in PTH levels. Calcium levels were raised and it showed no increase in serum PTH. Diagnosis?",o:["Primary hyperparathyroidism","Secondary hyperparathyroidism","Pseudo hyperparathyroidism","CRF"],a:0,e:"Hypercalcemia with hypophosphatemia, elevated PTH given but no increase in PTH confirms Primary Hyperparathyroidism as the underlying autonomous PTH excess causing these metabolic derangements.<br><br>Take Notes: High Ca + low PO4 + elevated PTH autonomously → primary hyperparathyroidism | Parathyroid adenoma → most common cause."},
/*152*/{q:"Corpus striatum contains: Caudate-putamen. Globus pallidus striatum contains: Basal nucleus of Meynert(forebrain):",o:["Acetylcholine","Dopamine","Not Epinephrine","Serotonin"],a:0,e:"The Basal Nucleus of Meynert contains large cholinergic neurons that provide widespread Acetylcholine innervation to the cerebral cortex; its degeneration causes Alzheimer's disease.<br><br>Take Notes: Nucleus of Meynert → Acetylcholine → cortical innervation | Degeneration → Alzheimer's disease."},
/*153*/{q:"Pain, temperature and crude touch lost it. The condition is carried by which of following tract?",o:["Anterolateral Spinothalamic tract","DCML","Lateral tract","Trigeminothalamic tract"],a:0,e:"Pain, temperature, and crude touch are carried by the Anterolateral Spinothalamic Tract after crossing at the level of entry in the spinal cord, ascending contralaterally to the thalamus.<br><br>Take Notes: Lateral spinothalamic tract → pain and temperature | Anterior spinothalamic tract → crude touch."},
/*154*/{q:"A neurologist stimulated Locus Ceruleus. Which of the Nucleus stimulated Locus Ceruleus. A patient complains of dryness of mouth with unilateral intrinsic numbness along the hand. The Posit ganglion fibers from the pterygopalatine ganglion is:",o:["Mandibular Nerve","Maxillary Nerve","Facial Nerve","Ophthalmic Nerve"],a:1,e:"The pterygopalatine (sphenopalatine) ganglion is a parasympathetic ganglion suspended from the Maxillary Nerve in the pterygopalatine fossa, conveying secretomotor fibers to lacrimal and nasal glands.<br><br>Take Notes: Pterygopalatine ganglion → suspended from Maxillary nerve | Post-ganglionic fibers → carried by maxillary branch to lacrimal and nasal glands."},
/*155*/{q:"The hip bent forward, the structure which of the following ligament contains: Which of the following structure is in hepatoduodenal ligament:",o:["Hepatic Artery","Celiac Trunk","IVC","Aorta"],a:0,e:"The Hepatoduodenal Ligament (free edge of lesser omentum) contains the portal triad: Hepatic Artery (proper), portal vein, and common bile duct.<br><br>Take Notes: Hepatoduodenal ligament → hepatic artery + portal vein + CBD | Pringle maneuver → compresses this ligament to stop hepatic bleeding."},
/*156*/{q:"A 20-year-old male presents with sudden onset severe headache described as 'worst headache of his life', neck stiffness and photophobia. CT scan of head is normal. What is the most appropriate next investigation?",o:["MRI brain with contrast","Lumbar puncture for CSF analysis","Cerebral angiography","EEG"],a:1,e:"Sudden severe headache (thunderclap) with meningism and a normal CT scan requires Lumbar Puncture to detect xanthochromia indicating subarachnoid hemorrhage, which CT can miss in early or small bleeds.<br><br>Take Notes: Thunderclap headache + normal CT → lumbar puncture for xanthochromia | SAH → sentinel headache, Berry aneurysm rupture."},
/*157*/{q:"A patient complains of dryness of mouth with decreased secretion of lacrimal gland. The Serotonin secreted from the patient complains. Raphe nucleus(brain stem) contains:",o:["Dopamine","Acetylcholine","Not Epinephrine","Serotonin"],a:3,e:"The Raphe Nuclei of the brainstem are the primary source of Serotonin (5-HT) in the CNS; serotonin projections from raphe nuclei regulate mood, sleep, and autonomic functions.<br><br>Take Notes: Raphe nuclei → serotonin | Substantia nigra → dopamine | Locus ceruleus → norepinephrine."},
/*158*/{q:"Frank-Starling law states that Force of Heart Contraction depends upon:",o:["Increased cardiac muscle fiber stretch","Increased cardiac contractility","Proportional to initial length of Myocardial Fiber","Decreased Cardiac Contractility"],a:2,e:"The Frank-Starling law states that the force of cardiac contraction is proportional to the initial length (end-diastolic volume) of the myocardial fiber before contraction.<br><br>Take Notes: Frank-Starling law → force of contraction proportional to initial fiber length | Greater EDV → greater stretch → greater SV."},
/*159*/{q:"Largest area of Sternocostal surface covering on X-ray is formed by Right Ventricle. What is the nerve supply of internal anal sphincter?",o:["Sympathetic (L1-L2) hypogastric plexus","Pudendal nerve (S2-S4)","Inferior rectal nerve","Pelvic splanchnic nerves (S2-S4)"],a:0,e:"The Internal Anal Sphincter (smooth muscle) is innervated by Sympathetic nerves from the hypogastric plexus (L1-L2) which maintain resting tone, and parasympathetics cause relaxation.<br><br>Take Notes: Internal anal sphincter → sympathetic (L1-L2) → maintains tone | External anal sphincter → pudendal nerve (S2-S4)."},

];
